// Material issue (part 16.04): an issue slip against a work authorisation (or a material request) to a crew, a subcontractor (free or chargeable) or equipment; the receiver acknowledges with a code or a signature and only then does the stock go out, at the average rate, charged
// to the WBS and cost code. Unused material comes back on a site return at the rate it left. The free-issue ledger sets what each subcontractor was given against what the norms entitle them to. Quantities are thousandths, rates and values paise, percentages x10000.
export const INV_ISSUE_DOC = 'INV_ISSUE'; export const INV_RETURN_DOC = 'INV_SITE_RETURN';
export const ISSUE_STATUS = { DRAFT: 'Draft', SUBMITTED: 'Waiting for approval', RETURNED: 'Returned for correction', APPROVED: 'Ready to hand over', POSTED: 'Issued', REJECTED: 'Rejected', CANCELLED: 'Cancelled' };
export const RETURN_STATUS = { DRAFT: 'Draft', SUBMITTED: 'Waiting for approval', RETURNED: 'Returned for correction', APPROVED: 'Approved and posted', REJECTED: 'Rejected', CANCELLED: 'Cancelled' };
export const ISSUE_TYPES = { OWN_CREW: 'To own crew (consumption)', SUBCO_FREE: 'Free issue to subcontractor', SUBCO_CHARGEABLE: 'Chargeable issue to subcontractor', EQUIPMENT: 'To equipment' };
export const CONDITIONS = { GOOD: 'Good: back into stock', DAMAGED: 'Damaged: held for inspection', SCRAP: 'Scrap: not back into stock' };
const EDITABLE = ['DRAFT', 'RETURNED'];
const hash = (t) => createHash('sha256').update(String(t)).digest('hex');

controlRegistry.define({
  code: 'CP-INV-01', module: 'inv', stage: 'VERIFY', description: 'Material issued without a work authorisation, or beyond its authorised quantity, needs an approved exception', enforcement: 'EXCEPTION', evidenceRequired: false, escalationLevel: 1, ownerRole: 'CM', mode: 'ENFORCE',
  evaluate: ({ context }) => ({ pass: false, message: context.message ?? 'Material is issued beyond what the work authorisation allows', details: { ref: context.ref ?? null, items: context.items ?? null } }),
});
for (const [key, def, description, min, max] of [
  ['inv.issue.wa_tolerance_pct', 0, 'FR-03: how much more than the authorised quantity of the work authorisation may be issued without an exception. Percent x10000 (5% is 50000).', 0, 1000000],
  ['inv.issue.ack_minutes', 30, 'How long the receiver code of an issue slip stays valid, in minutes.', 1, 1440],
]) if (!parameterRegistry.get(key)) parameterRegistry.define({ key, dataType: 'integer', default: def, scopes: ['system', 'company'], description, min, max });

export const issueList = defineList({
  code: 'inv.issues', label: 'Material issues', permission: 'inv.issue.view', from: 'inv_issues x JOIN inv_stores s ON s.id = x.store_id LEFT JOIN site_work_authorisations w ON w.id = x.wa_id', where: 'x.deleted_at IS NULL', searchable: ['x.doc_no', 'x.issued_to_name', 'w.wa_no', 's.code'], defaultSort: '-date',
  columns: {
    docNo: { sql: 'x.doc_no', type: 'text', label: 'Issue slip' }, date: { sql: 'x.issue_date', type: 'date', label: 'Date' }, store: { sql: 's.code', type: 'text', label: 'Store' }, type: { sql: 'x.issue_type', type: 'enum', label: 'Type', options: Object.entries(ISSUE_TYPES) }, wa: { sql: "COALESCE(w.wa_no, '')", type: 'text', label: 'Work authorisation' }, issuedTo: { sql: 'x.issued_to_name', type: 'text', label: 'Issued to' },
    acknowledged: { sql: "CASE WHEN x.receiver_ack = 1 THEN 'Y' ELSE 'N' END", type: 'enum', label: 'Receiver acknowledged', options: [['Y', 'Acknowledged'], ['N', 'Not yet']] }, status: { sql: 'x.status', type: 'enum', label: 'Status', options: Object.entries(ISSUE_STATUS) },
  },
});
export const returnList = defineList({
  code: 'inv.site_returns', label: 'Site returns', permission: 'inv.site_return.view', from: 'inv_site_returns x JOIN inv_stores s ON s.id = x.store_id JOIN inv_issues i ON i.id = x.issue_id', where: 'x.deleted_at IS NULL', searchable: ['x.doc_no', 'i.doc_no', 'x.from_name'], defaultSort: '-date',
  columns: { docNo: { sql: 'x.doc_no', type: 'text', label: 'Return' }, date: { sql: 'x.return_date', type: 'date', label: 'Date' }, store: { sql: 's.code', type: 'text', label: 'Store' }, issue: { sql: 'i.doc_no', type: 'text', label: 'Issue slip' }, from: { sql: 'x.from_name', type: 'text', label: 'Returned by' }, condition: { sql: 'x.condition', type: 'enum', label: 'Condition', options: Object.entries(CONDITIONS) }, status: { sql: 'x.status', type: 'enum', label: 'Status', options: Object.entries(RETURN_STATUS) } },
});

const d3 = (n) => (n == null ? null : n / 1000); const t3 = (n) => Math.round(Number(n) * 1000); const valueOf = (qty, rate) => Math.round((qty * rate) / 1000);

