      o.lines = lineRows(r.id).map((l) => ({ id: l.id, lineNo: l.line_no, itemId: l.item_id, item: `${l.icode} ${l.iname}`, uom: l.uom, qty: d3(l.qty), authorisedQty: d3(l.authorised_qty), issuedBefore: d3(l.issued_before), excessQty: d3(l.excess_qty), batchNo: l.batch_no, rate: mask(l.rate, actor, r.org_project_id), value: mask(l.value, actor, r.org_project_id), chargeRate: mask(l.charge_rate, actor, r.org_project_id), returnedQty: d3(l.returned_qty) }));
      o.postings = db.prepare("SELECT l.doc_no, l.txn_date, l.qty_out, l.value, g.line_no FROM inv_stock_ledger l JOIN inv_issue_lines g ON g.id = CAST(l.source_id AS INTEGER) WHERE l.source_type = 'inv_issue_line' AND g.issue_id = ? ORDER BY l.id").all(r.id).map((p) => ({ docNo: p.doc_no, date: p.txn_date, qty: d3(p.qty_out), lineNo: p.line_no, value: mask(p.value, actor, r.org_project_id) }));
