    const pid = w?.org_project_id ?? mr?.org_project_id ?? b.projectId ?? store.org_project_id; if (!pid) fail([{ field: 'projectId', message: 'Choose the project the material is issued to' }]); if (store.org_project_id && store.org_project_id !== pid) throw unprocessable('That store belongs to another project.'); need(actor, 'inv.issue.create', 'issue material', pid);
    const to = b.issuedTo; if (to.type === 'SUBCONTRACTOR' && !partner(rid(to.id ?? 0))) fail([{ field: 'issuedTo', message: 'Choose the subcontractor' }]); if (to.type === 'CREW' && to.id && !db.prepare('SELECT 1 FROM hr_crews WHERE id = ? AND company_id = ?').get(rid(to.id), actor.companyId)) fail([{ field: 'issuedTo', message: 'No such crew' }]);
    if (['SUBCO_FREE', 'SUBCO_CHARGEABLE'].includes(b.type) && to.type !== 'SUBCONTRACTOR') fail([{ field: 'issuedTo', message: 'A subcontractor issue goes to a subcontractor' }]); if (b.type === 'OWN_CREW' && !['CREW', 'PERSON'].includes(to.type)) fail([{ field: 'issuedTo', message: 'An issue to the own crew goes to a crew or a person' }]); if (b.type === 'EQUIPMENT' && to.type !== 'EQUIPMENT') fail([{ field: 'issuedTo', message: 'Name the equipment' }]);
